function bufferPH(pKa, acidConc, baseConc){
  if(!(acidConc > 0)) return NaN;
  return pKa + Math.log10(baseConc / acidConc);
}
function bufferPHmoles(pKa, nAcid, nBase){
  if(!(nAcid > 0)) return NaN;
  return pKa + Math.log10(nBase / nAcid);
}
function neededBase(pKa, acidConc, targetPH){
  if(!(acidConc > 0)) return NaN;
  return acidConc * Math.pow(10, targetPH - pKa);
}
var EXPORTS = { bufferPH:bufferPH, bufferPHmoles:bufferPHmoles, neededBase:neededBase };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BufferForgePure = EXPORTS; }
